CREATE DATABASE IF NOT EXISTS gamevault CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE gamevault;

CREATE TABLE IF NOT EXISTS categories (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(50) NOT NULL UNIQUE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS products (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(180) NOT NULL,
    price DECIMAL(10,2) NOT NULL,
    image VARCHAR(255) NOT NULL,
    category_id INT UNSIGNED NOT NULL,
    description TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_products_categories FOREIGN KEY (category_id) REFERENCES categories(id),
    CONSTRAINT chk_products_price CHECK (price >= 0)
) ENGINE=InnoDB;

INSERT INTO categories (name) VALUES
('FPS'),
('Puzzle'),
('RPG'),
('Action'),
('Strategy'),
('Adventure')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO products (id, name, price, image, category_id, description) VALUES
(1, 'Half-Life: Alyx', 20.00, 'assets/images/Alyx.webp', (SELECT id FROM categories WHERE name = 'FPS'), 'A história acompanha Alyx Vance em uma luta contra a Combine, uma organização alienígena que controla a humanidade. Ambientado entre os acontecimentos de Half-Life e Half-Life 2, o jogo apresenta uma aventura em realidade virtual com exploração, combates e resolução de enigmas. Utilize diferentes armas e interaja com o ambiente de maneiras realistas para sobreviver aos perigos de City 17.'),
(2, 'Portal 2', 10.00, 'assets/images/p2.jpg', (SELECT id FROM categories WHERE name = 'Puzzle'), 'Portal 2 é um jogo de quebra-cabeças em primeira pessoa no qual você utiliza uma arma capaz de criar dois portais interligados. Com ela, é possível atravessar grandes distâncias, manipular objetos e encontrar soluções criativas para diferentes desafios. Durante a aventura, você explora as instalações da Aperture Science e encontra personagens como GLaDOS, que apresenta desafios cada vez mais complexos. O jogo também oferece um modo cooperativo com fases próprias para dois jogadores.'),
(3, 'The Witcher 3: Wild Hunt', 32.00, 'assets/images/twwh.webp', (SELECT id FROM categories WHERE name = 'RPG'), 'Em The Witcher 3: Wild Hunt, você assume o papel de Geralt de Rívia, um bruxo especializado na caça de monstros que percorre um mundo de fantasia medieval. Sua principal missão é encontrar Ciri, sua filha adotiva, enquanto enfrenta criaturas perigosas, participa de conflitos políticos e conhece diferentes personagens. O jogo oferece um vasto mundo para explorar, diversas missões secundárias e escolhas que podem alterar o desenvolvimento da história. Também é possível fabricar equipamentos, preparar poções e desenvolver habilidades para enfrentar inimigos cada vez mais fortes.'),
(4, 'Doom Eternal', 49.99, 'assets/images/doomE.jpg', (SELECT id FROM categories WHERE name = 'FPS'), 'Em DOOM Eternal, você assume o controle do Doom Slayer, um guerreiro encarregado de impedir que forças demoníacas destruam a humanidade. Enfrente enormes hordas de inimigos utilizando um arsenal variado de armas, incluindo espingardas, lançadores de foguetes e equipamentos especiais. O combate exige velocidade, precisão e estratégia, recompensando jogadores que sabem alternar entre armas e habilidades durante as batalhas.'),
(5, 'The Witness', 29.99, 'assets/images/tw.webp', (SELECT id FROM categories WHERE name = 'Puzzle'), 'The Witness coloca o jogador em uma ilha misteriosa repleta de construções, paisagens e centenas de quebra-cabeças. Seu principal desafio é resolver painéis que exigem observação, raciocínio lógico e compreensão de diferentes regras. Conforme você avança, os enigmas ficam mais complexos e passam a utilizar elementos do próprio ambiente. Sem depender de explicações constantes, o jogo incentiva a descoberta e a experimentação.'),
(6, 'Elden Ring', 59.99, 'assets/images/er.webp', (SELECT id FROM categories WHERE name = 'RPG'), 'Elden Ring apresenta um enorme mundo de fantasia conhecido como Terras Intermédias, onde o jogador assume o papel de um Maculado em busca do título de Lorde Prístino. Explore diferentes regiões, descubra ruínas, cavernas e castelos, além de enfrentar criaturas e chefes extremamente poderosos. O jogo permite personalizar completamente seu personagem, escolhendo armas, armaduras, magias e habilidades de combate. Sua exploração livre e seus desafios oferecem diversas possibilidades para desenvolver seu próprio estilo de jogo.'),
(7, 'God of War Ragnarök', 39.99, 'assets/images/gow.jpg', (SELECT id FROM categories WHERE name = 'Action'), 'God of War Ragnarök acompanha Kratos e seu filho Atreus durante os acontecimentos que antecedem o Ragnarök, o grande conflito da mitologia nórdica. Enquanto tentam descobrir o futuro e proteger aqueles que amam, os dois precisam enfrentar deuses, monstros e guerreiros de diferentes reinos. O jogo apresenta combates intensos com armas como o Machado Leviatã e as Lâminas do Caos, além de melhorias de equipamentos e habilidades. A aventura também desenvolve a relação entre pai e filho, explorando temas como família, responsabilidade e destino.'),
(8, 'Call of Duty: Modern Warfare II', 54.99, 'assets/images/cod.jpg', (SELECT id FROM categories WHERE name = 'Action'), 'Call of Duty: Modern Warfare II apresenta uma campanha militar moderna envolvendo operações internacionais e ameaças terroristas. O jogador participa de missões ao lado de integrantes da Força-Tarefa 141, utilizando diferentes armas, equipamentos e estratégias para cumprir seus objetivos. Além da campanha, o jogo oferece modos multiplayer competitivos, nos quais jogadores enfrentam equipes adversárias em diferentes mapas e modalidades. Também conta com o modo Special Ops, que permite realizar missões cooperativas com outros jogadores.'),
(9, 'Civilization VI', 34.99, 'assets/images/cvi.webp', (SELECT id FROM categories WHERE name = 'Strategy'), 'Civilization VI é um jogo de estratégia por turnos no qual você assume o comando de uma civilização e precisa conduzi-la desde os primeiros períodos da história até a era moderna. Construa cidades, desenvolva tecnologias, pesquise novas descobertas e administre recursos para fortalecer seu império. Durante a partida, será necessário negociar com outras civilizações, formar alianças ou entrar em guerras para conquistar territórios. Existem diferentes maneiras de alcançar a vitória, como desenvolvimento científico, domínio militar, influência cultural e poder religioso.'),
(10, 'Age of Empires II: Definitive Edition', 39.99, 'assets/images/aoe.webp', (SELECT id FROM categories WHERE name = 'Strategy'), 'Age of Empires II: Definitive Edition é um jogo de estratégia em tempo real no qual você comanda civilizações históricas em diferentes períodos da humanidade. Comece com uma pequena comunidade, colete recursos, construa estruturas e desenvolva seu exército para enfrentar adversários. Cada civilização possui unidades e características próprias, permitindo diferentes estratégias durante as partidas. O jogo também oferece campanhas históricas, partidas contra inteligência artificial e modos multiplayer para competir com outros jogadores.'),
(11, 'Red Dead Redemption 2', 59.99, 'assets/images/rdr2.webp', (SELECT id FROM categories WHERE name = 'Adventure'), 'Red Dead Redemption 2 acompanha Arthur Morgan, um integrante da gangue de Dutch van der Linde durante o declínio do Velho Oeste americano. Em meio a perseguições, conflitos e dificuldades financeiras, o grupo tenta sobreviver enquanto o mundo ao seu redor passa por grandes transformações. O jogador pode explorar cidades, florestas e montanhas, participar de missões, caçar animais e interagir com diversos personagens. A narrativa apresenta escolhas e acontecimentos que desenvolvem os relacionamentos entre os integrantes da gangue.'),
(12, 'Uncharted 4: A Thief''s End', 49.99, 'assets/images/u4.jpg', (SELECT id FROM categories WHERE name = 'Adventure'), 'Uncharted 4: A Thief’s End acompanha Nathan Drake, um explorador que acreditava ter deixado suas aventuras para trás, mas acaba retornando à vida de caçador de tesouros após o reaparecimento de seu irmão Sam. Juntos, eles partem em busca do lendário tesouro do pirata Henry Avery, atravessando diferentes regiões e enfrentando perigos pelo caminho. A jogabilidade mistura exploração, escaladas, resolução de enigmas e combates contra inimigos. A história apresenta uma aventura cinematográfica que explora o passado de Nathan e suas relações pessoais.'),
(13, 'Titanfall 2', 29.99, 'assets/images/t2.jpg', (SELECT id FROM categories WHERE name = 'FPS'), 'Titanfall 2 apresenta um futuro em que soldados conhecidos como pilotos lutam ao lado de enormes máquinas de guerra chamadas Titãs. Você controla Jack Cooper, um soldado que acaba formando uma parceria com o Titã BT-7274 durante uma missão perigosa. A campanha combina tiroteios intensos, movimentação rápida, saltos entre plataformas e combates com robôs gigantes, oferecendo uma experiência variada e cinematográfica.'),
(14, 'Tetris Effect', 24.99, 'assets/images/tec.webp', (SELECT id FROM categories WHERE name = 'Puzzle'), 'Tetris Effect: Connected apresenta uma versão moderna do clássico jogo de encaixar blocos, combinando sua jogabilidade tradicional com músicas, efeitos visuais e cenários dinâmicos. O objetivo é organizar as peças que caem na tela para completar linhas e evitar que elas alcancem o topo. Diferentes modos oferecem desafios variados, incluindo partidas competitivas e experiências cooperativas. Cada movimento acompanha a trilha sonora, criando uma experiência visual e musical bastante característica.'),
(15, 'Cyberpunk 2077', 59.99, 'assets/images/2077.jpg', (SELECT id FROM categories WHERE name = 'RPG'), 'Cyberpunk 2077 se passa em Night City, uma gigantesca metrópole futurista dominada por grandes corporações, tecnologias avançadas e conflitos entre diferentes grupos. Você controla V, um mercenário que acaba envolvido em uma missão que pode mudar completamente sua vida. Durante a aventura, é possível explorar a cidade, realizar trabalhos, melhorar seu corpo com implantes tecnológicos e utilizar diferentes armas e habilidades. As decisões tomadas ao longo da história influenciam os acontecimentos e podem levar a diferentes finais.')
ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    price = VALUES(price),
    image = VALUES(image),
    category_id = VALUES(category_id),
    description = VALUES(description);
